import json
import os
import sys
from datetime import datetime
from pathlib import Path

def load_json_file(file_path):
    """Load JSON data from a file."""
    with open(file_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str):
    """Parse a date string in YYYY-MM-DD format, handling potential time components."""
    if not date_str:
        return None
    # Split to get just the date part if there's a time
    date_part = date_str.split()[0] if ' ' in date_str else date_str
    try:
        return datetime.strptime(date_part, '%Y-%m-%d').date()
    except ValueError:
        return None

def extract_fact_value(award, fact_name, rule_id):
    """Extract the value for a specific fact from an award based on the rule."""
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            date_str = award.get("period_of_performance", {}).get("start_date")
            return parse_date(date_str)
        elif fact_name == "performance end":
            date_str = award.get("period_of_performance", {}).get("end_date")
            return parse_date(date_str)
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            value = award.get("total_obligation")
            # Handle null/None
            if value is None:
                return None
            # Convert to float if it's a number
            try:
                return float(value)
            except (ValueError, TypeError):
                return None
        elif fact_name == "potential value":
            value = award.get("base_and_all_options")
            if value is None:
                return None
            try:
                return float(value)
            except (ValueError, TypeError):
                return None
    return None

def process_pair(packet_dir, pair, facts_map, all_awards):
    """Process a single pair (rule_id::entity) and return its facts."""
    rule_id, entity = pair.split("::", 1)
    fact_names = facts_map.get(rule_id, [])

    # Find all awards matching this entity (generated_unique_award_id)
    matching_awards = [award for award in all_awards if award.get("generated_unique_award_id") == entity]

    result = {}

    for fact_name in fact_names:
        values = []
        documents = []

        for award in matching_awards:
            value = extract_fact_value(award, fact_name, rule_id)
            if value is not None:
                values.append(value)
                # Document is the file name without extension
                documents.append("usaspending_awards")

        if not values:
            result[fact_name] = "ABSENT"
        elif len(set(values)) > 1:
            result[fact_name] = "CONFLICT"
        else:
            # Format the value appropriately
            val = values[0]
            # Check if it's a date object (datetime.date)
            if hasattr(val, 'strftime'):  # Check if it's a date-like object
                formatted = val.strftime('%Y-%m-%d')
            elif isinstance(val, float) or isinstance(val, int):
                # Format as decimal string without unnecessary trailing zeros
                formatted = format(float(val), 'f').rstrip('0').rstrip('.')
            else:
                formatted = str(val)

            result[fact_name] = [formatted, documents[0]]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    all_awards = load_json_file(awards_file)

    # Process each pair
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(packet_dir, pair, manifest["facts"], all_awards)

    # Print JSON result
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

