import json
import os
import sys
from datetime import datetime, date, timedelta
from pathlib import Path

def load_json_file(file_path):
    """Load JSON data from a file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def parse_date(date_str):
    """Parse a date string in YYYY-MM-DD format, handling None and empty strings."""
    if not date_str:
        return None
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return None

def extract_fact_value(award, fact_name, rule_id):
    """Extract the value for a specific fact from an award based on the rule."""
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            date_str = award.get("period_of_performance", {}).get("start_date")
            return parse_date(date_str)
        elif fact_name == "performance end":
            date_str = award.get("period_of_performance", {}).get("end_date")
            return parse_date(date_str)
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            value = award.get("total_obligation")
            return float(value) if value is not None else None
        elif fact_name == "potential value":
            value = award.get("base_and_all_options")
            return float(value) if value is not None else None
    return None

def format_value(value, fact_name):
    """Format the extracted value for output."""
    if value is None:
        return "ABSENT"
    if isinstance(value, date):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, float):
        # Format as decimal string without unnecessary trailing zeros
        return format(value, 'f').rstrip('0').rstrip('.')
    return str(value)

def process_packet(packet_dir, manifest):
    """Process the packet directory and manifest to extract required facts."""
    # Load the awards data
    awards_file = Path(packet_dir) / "usaspending_awards.json"
    awards_data = load_json_file(awards_file)
    if awards_data is None:
        return {}

    # Create a mapping from generated_unique_award_id to award
    award_map = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            award_map[award_id] = award

    # Process each pair in the manifest
    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        if entity not in award_map:
            # Award not found, all facts are ABSENT
            result[pair] = {fact: "ABSENT" for fact in manifest["facts"][rule_id]}
            continue

        award = award_map[entity]
        fact_results = {}

        # Extract each fact for this rule
        for fact_name in manifest["facts"][rule_id]:
            value = extract_fact_value(award, fact_name, rule_id)
            if value is None:
                fact_results[fact_name] = "ABSENT"
            else:
                # Format the value and include document name
                formatted_value = format_value(value, fact_name)
                fact_results[fact_name] = [formatted_value, "usaspending_awards"]

        result[pair] = fact_results

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    manifest = load_json_file(manifest_path)
    if manifest is None:
        print(json.dumps({}))
        sys.exit(1)

    # Process the packet
    result = process_packet(packet_dir, manifest)

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

