import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def load_json_file(file_path):
    """Load JSON data from a file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def parse_date(date_str):
    """Parse a date string in YYYY-MM-DD format, handling None and empty strings."""
    if not date_str:
        return None
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return None

def extract_facts_for_pair(pair_id, rule_id, facts, data):
    """Extract the required facts for a given pair from the data."""
    result = {}
    for fact_name in facts:
        if rule_id == "usa.period_3y":
            if fact_name == "performance start":
                # Extract from period_of_performance.start_date
                value = data.get("period_of_performance", {}).get("start_date")
                if value is None:
                    result[fact_name] = "ABSENT"
                else:
                    result[fact_name] = [value, "usaspending_awards"]
            elif fact_name == "performance end":
                # Extract from period_of_performance.end_date
                value = data.get("period_of_performance", {}).get("end_date")
                if value is None:
                    result[fact_name] = "ABSENT"
                else:
                    result[fact_name] = [value, "usaspending_awards"]
        elif rule_id == "usa.obligated_95":
            if fact_name == "amount obligated":
                # Extract from total_obligation
                value = data.get("total_obligation")
                if value is None:
                    result[fact_name] = "ABSENT"
                else:
                    # Format as decimal string
                    result[fact_name] = [str(value), "usaspending_awards"]
            elif fact_name == "potential value":
                # Extract from base_and_all_options
                value = data.get("base_and_all_options")
                if value is None:
                    result[fact_name] = "ABSENT"
                else:
                    # Format as decimal string
                    result[fact_name] = [str(value), "usaspending_awards"]
    return result

def main(packet_directory, manifest_path):
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    # Load usaspending_awards data
    awards_path = os.path.join(packet_directory, "usaspending_awards.json")
    awards_data = load_json_file(awards_path)
    if awards_data is None:
        # If file not found or invalid JSON, return ABSENT for all
        awards_data = []

    # Build a mapping from generated_unique_award_id to award record
    awards_map = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_map[award_id] = award

    # Prepare result
    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts_needed = facts_by_rule.get(rule_id, [])

        if entity in awards_map:
            award_record = awards_map[entity]
            fact_values = extract_facts_for_pair(pair, rule_id, facts_needed, award_record)

            # Check for conflicts: if multiple awards with same ID? Not in this dataset.
            # Since each award ID is unique, no conflict detection needed across records.
            result[pair] = fact_values
        else:
            # Award not found, all facts are ABSENT
            result[pair] = {fact: "ABSENT" for fact in facts_needed}

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_directory = sys.argv[1]
    manifest_path = sys.argv[2]

    main(packet_directory, manifest_path)

