import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def load_json_file(file_path):
    """Load JSON data from a file."""
    with open(file_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str):
    """Parse a date string in YYYY-MM-DD format."""
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return None

def extract_facts_from_award(award, rule_id, facts_needed):
    """Extract required facts from a single award based on the rule."""
    result = {}

    if rule_id == "usa.period_3y":
        # Extract performance start and end dates
        period = award.get("period_of_performance", {})
        start_date = period.get("start_date")
        end_date = period.get("end_date")

        if "performance start" in facts_needed:
            if start_date:
                result["performance start"] = [start_date, "usaspending_awards"]
            else:
                result["performance start"] = "ABSENT"

        if "performance end" in facts_needed:
            if end_date:
                result["performance end"] = [end_date, "usaspending_awards"]
            else:
                result["performance end"] = "ABSENT"

    elif rule_id == "usa.obligated_95":
        # Extract amount obligated and potential value
        amount_obligated = award.get("total_obligation")
        potential_value = award.get("base_and_all_options")

        if "amount obligated" in facts_needed:
            if amount_obligated is not None:
                # Format as decimal string
                result["amount obligated"] = [str(float(amount_obligated)), "usaspending_awards"]
            else:
                result["amount obligated"] = "ABSENT"

        if "potential value" in facts_needed:
            if potential_value is not None:
                # Format as decimal string
                result["potential value"] = [str(float(potential_value)), "usaspending_awards"]
            else:
                result["potential value"] = "ABSENT"

    return result

def process_packet(packet_dir, manifest):
    """Process the packet directory according to the manifest."""
    # Load the awards data
    awards_file = Path(packet_dir) / "usaspending_awards.json"
    awards_data = load_json_file(awards_file)

    # Create a mapping from generated_unique_award_id to award
    awards_by_id = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_by_id[award_id] = award

    # Process each pair in the manifest
    results = {}

    for pair in manifest["pairs"]:
        rule_id, entity_id = pair.split("::", 1)

        if entity_id not in awards_by_id:
            # Award not found, all facts are ABSENT
            facts_needed = manifest["facts"][rule_id]
            results[pair] = {fact: "ABSENT" for fact in facts_needed}
            continue

        award = awards_by_id[entity_id]
        facts_needed = manifest["facts"][rule_id]

        # Extract facts for this award and rule
        facts = extract_facts_from_award(award, rule_id, facts_needed)

        # Check for conflicts (multiple values for the same fact)
        # Since we're only looking at one document per fact, conflicts can't occur
        # within a single award. But if there were multiple awards with the same ID,
        # we'd need to handle that. However, the data structure suggests unique IDs.

        results[pair] = facts

    return results

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load the manifest
    manifest = load_json_file(manifest_path)

    # Process the packet
    results = process_packet(packet_dir, manifest)

    # Output results as JSON
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

