            end_date = award.get("period_of_performance", {}).get("end_date")
            return end_date, "usaspending_awards"
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            obligated = award.get("total_obligation")
            return obligated, "usaspending_awards"
        elif fact_name == "potential value":
            potential = award.get("base_and_all_options")
            return potential, "usaspending_awards"
    return None, None

def process_pair(packet_dir, pair, facts_list, awards_data):
    """Process a single pair (rule_id::entity) and return the fact values."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    # Find the award with matching generated_unique_award_id
    award = None
    for a in awards_data:
        if a.get("generated_unique_award_id") == entity:
            award = a
            break

    if award is None:
        # If award not found, all facts are ABSENT
        for fact_name in facts_list[rule_id]:
            result[fact_name] = "ABSENT"
        return result

    # Collect values for each fact
    fact_values = {}
    for fact_name in facts_list[rule_id]:
        value, source = extract_fact_value(award, fact_name, rule_id)
        if value is None:
            fact_values[fact_name] = ("ABSENT", None)
        else:
            fact_values[fact_name] = (value, source)

    # Check for conflicts (multiple values for same fact from different sources)
    # Since each fact has only one source per rule, conflicts can't happen across sources.
    # But we need to check if the same fact appears multiple times in different awards?
    # Actually, each entity is unique, so no conflict across awards for same entity.
    # However, if the same fact appears multiple times within the same award? Not in our rules.

    # Format the result
    for fact_name in facts_list[rule_id]:
        value, source = fact_values[fact_name]
        if value == "ABSENT":
            result[fact_name] = "ABSENT"
        else:
            # Format dates and amounts
            if fact_name in ["performance start", "performance end"]:
                # Ensure date format is YYYY-MM-DD
                date_val = parse_date(value)
                if date_val:
                    value = date_val.strftime("%Y-%m-%d")
                else:
                    value = str(value)
            elif fact_name in ["amount obligated", "potential value"]:
                # Format as decimal string
                if value is None:
                    result[fact_name] = "ABSENT"
                    continue
                # Convert to string, removing trailing zeros if needed
                try:
                    # Ensure it's a number
                    num = float(value)
                    # Format without unnecessary trailing zeros
                    if num.is_integer():
                        value = str(int(num))
                    else:
                        value = str(num).rstrip('0').rstrip('.')
                except (ValueError, TypeError):
                    value = str(value)
            result[fact_name] = [value, source]

    return result

def main(packet_dir, manifest_path):
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts = manifest["facts"]

    # Load awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_data = load_json_file(awards_file)
    if awards_data is None:
        # If file not found or invalid, return ABSENT for all
        result = {}
        for pair in pairs:
            rule_id = pair.split("::", 1)[0]
            result[pair] = {fact: "ABSENT" for fact in facts[rule_id]}
        print(json.dumps(result, indent=2))
        return

    # Process each pair
    output = {}
    for pair in pairs:
        output[pair] = process_pair(packet_dir, pair, facts, awards_data)

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    main(packet_dir, manifest_path)

